command:
// ==========================================
// LUNAS WIRKUNG: TANZ DER KLINGEN (APHASMA)
//
// - Voraussetzung: Effekt "Aphasmas Schleier" auf dem Wirkenden aktiv
// - mehrere Targets: alle gültigen Erwachten = Erfolg, ungültige Targets = Misserfolg
// - Wirkender erhält "Tanz der Klingen (Aphasma)"
// - Ziele erhalten "Tanz der Klingen (Aphasma) - Verzaubert":
//   * Willenskraft -(QS * 4) über system.skillModifiers.FW (mode 0)
//   * Fernkampf-AT, Nahkampf-AT & Zauberschaden -(QS) (mode 2)
// - gekoppeltes Cleanup: Ende beim Tänzer entfernt automatisch alle Ziel-Debuffs
// - Live-Wächter erinnert bei Angriffsproben verzauberter Ziele an die Willenskraft-Probe
// - gespeicherte Ziele | GM-Button | gemeinsame Karte über GabenUI
// ==========================================

(async function () {
    const macroUuid = this?.uuid || game.macros.getName("Tanz der Klingen")?.uuid || null;

    // +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++++++
    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
    const frameworkFehlt =
        !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.Effekt?.CheckTarget ||
        !globalThis.DSK?.EffektEnde?.Register || !globalThis.DSK?.QS?.Ermitteln ||
        !globalThis.DSK?.Token?.Finde || !globalThis.DSK?.Wesen?.match ||
        !globalThis.DSK?.Empfaenger?.GMUndBesitzer ||
        !globalThis.DSK?.GMAnfrage?.Speichern || !globalThis.DSK?.GMAnfrage?.Finden ||
        !globalThis.DSK?.GMAnfrage?.Lesen || !globalThis.DSK?.GMAnfrage?.Loeschen ||
        !globalThis.DSK?.GabenUI?.GMMakroButton ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

    if (frameworkFehlt) {
        const fwMacro = await fromUuid(frameworkUuid);
        if (!fwMacro?.execute) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
        await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150));
    }

    const DSK_FW = globalThis.DSK;
    if (
        !DSK_FW?.Effekt?.Anwenden || !DSK_FW?.Effekt?.CheckTarget ||
        !DSK_FW?.EffektEnde?.Register || !DSK_FW?.QS?.Ermitteln ||
        !DSK_FW?.Token?.Finde || !DSK_FW?.Wesen?.match ||
        !DSK_FW?.Empfaenger?.GMUndBesitzer ||
        !DSK_FW?.GMAnfrage?.Speichern || !DSK_FW?.GMAnfrage?.Finden ||
        !DSK_FW?.GMAnfrage?.Lesen || !DSK_FW?.GMAnfrage?.Loeschen ||
        !DSK_FW?.GabenUI?.GMMakroButton ||
        !DSK_FW?.GabenUI?.AnfrageKarteErstellen ||
        !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren
    ) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework 01.02 wurde nicht vollständig geladen!");

    // +++ 2 - GRUNDDATEN & GLOBALE WÄCHTER ++++++++++++++++++++++++
    const gabenName = "Tanz der Klingen", vollerName = "Tanz der Klingen (Aphasma)", ahne = "Aphasma";
    const zielEffektName = `${vollerName} - Verzaubert`;
    const flagKey = "pendingTanzDerKlingenAphasma", endeKey = "aphasmaTanzDerKlingen";
    const endeText = "Der hypnotische Tanz endet. Der Tänzer ist wieder normal angreifbar und die Feinde sind vom Bann befreit.";
    const dauerText = "Solange getanzt wird";
    const iconBild = DSK_FW.Symbol(ahne);

    DSK_FW.EffektEnde.Register(endeKey, vollerName, endeText);

    // A) Gekoppeltes Cleanup: Hört das Aphasmakind auf zu tanzen, enden auch die Debuffs auf den Feinden
    if (globalThis._dskTanzDerKlingenCleanupHook) {
        Hooks.off("deleteActiveEffect", globalThis._dskTanzDerKlingenCleanupHook);
    }
    globalThis._dskTanzDerKlingenCleanupHook = Hooks.on("deleteActiveEffect", async effect => {
        const aktiverGM = game.users.find(u => u.isGM && u.active);
        const darfLoeschen = aktiverGM ? (game.user.isGM && game.user.id === aktiverGM.id) : game.user.isGM;
        if (!darfLoeschen || !effect) return;

        if ((effect.name || effect.label || "") !== vollerName) return;
        const parentUuid = effect.parent?.uuid;
        if (!parentUuid) return;

        const gepruefteActors = new Set();
        const alleActors = [
            ...(canvas.tokens?.placeables || []).map(t => t.actor).filter(Boolean),
            ...Array.from(game.actors || [])
        ];

        for (const actor of alleActors) {
            if (!actor?.uuid || gepruefteActors.has(actor.uuid)) continue;
            gepruefteActors.add(actor.uuid);

            const toDelete = (actor.effects || [])
                .filter(e =>
                    (e.name || e.label || "") === zielEffektName &&
                    e.getFlag("dsk", "linkedActorUuid") === parentUuid
                )
                .map(e => e.id);

            if (toDelete.length) {
                try {
                    await actor.deleteEmbeddedDocuments("ActiveEffect", toDelete);
                } catch (err) {
                    console.warn("Tanz der Klingen: Ziel-Debuff konnte beim Cleanup nicht entfernt werden.", err);
                }
            }
        }
    });

    // B) Live-Wächter: Erinnert an die Willenskraft-Probe, wenn ein verzauberter Feind angreift
    if (globalThis._dskTanzDerKlingenAttackHook) {
        Hooks.off("createChatMessage", globalThis._dskTanzDerKlingenAttackHook);
    }
    globalThis._dskTanzDerKlingenAttackHook = Hooks.on("createChatMessage", async message => {
        const aktiverGM = game.users.find(u => u.isGM && u.active);
        const darfSenden = aktiverGM ? (game.user.isGM && game.user.id === aktiverGM.id) : game.user.isGM;
        if (!darfSenden || !message) return;
        if (message.speaker?.alias === "System" || message.flags?.dsk?.isWatcherMsg) return;

        const rawText = [String(message.flavor || ""), String(message.content || "")].join(" ");
        const cleanText = rawText.replace(/<[^>]*>?/gm, " ").replace(/\s+/g, " ").trim();

        if (
            !cleanText.includes("Angriffsprobe") &&
            !cleanText.includes("Attacke") &&
            !cleanText.includes("Fernkampf") &&
            !cleanText.includes("Zauberprobe")
        ) return;

        const speakerToken = message.speaker?.token ? canvas.scene?.tokens?.get(message.speaker.token) : null;
        const angreiferActor = speakerToken?.actor || (message.speaker?.actor ? game.actors.get(message.speaker.actor) : null);
        if (!angreiferActor) return;

        const debuffEffekt = (angreiferActor.effects || []).find(e =>
            !e.disabled && (e.name || e.label || "") === zielEffektName
        );
        if (!debuffEffekt) return;

        const linkedCasterUuid = debuffEffekt.getFlag("dsk", "linkedActorUuid");
        let casterActor = null;
        if (linkedCasterUuid) {
            try {
                const doc = await fromUuid(linkedCasterUuid);
                casterActor = doc?.documentName === "Token" ? doc.actor : doc;
            } catch {}
        }

        // Prüfen, ob der Tänzer überhaupt noch tanzt
        if (casterActor) {
            const tanztNoch = (casterActor.effects || []).some(e =>
                !e.disabled && (e.name || e.label || "") === vollerName
            );
            if (!tanztNoch) return;
        }

        const qs = Math.max(1, Number(debuffEffekt.getFlag("dsk", "qs")) || 1);
        const willenskraftMalus = Number(debuffEffekt.getFlag("dsk", "willenskraftMalus")) || (qs * 4);
        const attackeMalus = Number(debuffEffekt.getFlag("dsk", "attackeMalus")) || qs;
        const angreiferName = speakerToken?.name || message.speaker?.alias || DSK_FW.ResolveTokenName(angreiferActor);
        const whisperTargets = casterActor ? DSK_FW.Empfaenger.GMUndBesitzer(casterActor) : DSK_FW.Empfaenger.GM();

        const whisperHtml = `
            <div style="font-family:'Signika',sans-serif;">
                ${DSK_FW.UI.Header(`${vollerName}<br>Tanz-Wächter Erinnerung`, iconBild)}
                <div class="dskbox2" style="margin-top:10px;">
                    <p style="font-size:0.95em;">
                        <b>${angreiferName}</b> greift an, ist aber vom <b>Tanz der Klingen</b> verzaubert!
                    </p>
                    <hr style="margin:8px 0;border:0;border-top:1px solid #c9bca6;">
                    <p style="margin-bottom:5px;color:#B30000;font-weight:bold;text-align:center;">
                        Hat ${angreiferName} die Willenskraft-Probe (−${willenskraftMalus}) bestanden?
                    </p>
                    <p style="font-size:0.85em;color:#555;text-align:center;margin-bottom:0;">
                        <i>(Die Erschwernis von −${attackeMalus} auf den Angriff wird vom System automatisch abgezogen.)</i>
                    </p>
                </div>
            </div>
        `;

        await ChatMessage.create({
            whisper: whisperTargets,
            speaker: { alias: "System" },
            flags: { dsk: { isWatcherMsg: true } },
            content: whisperHtml
        });
    });

    // +++ 3 - HELFER ++++++++++++++++++++++++++++++++++++++++++++++
    const raeumeQSAuf = async actor => {
        if (actor?.getFlag("world", "letzteGabenQS") !== undefined) await actor.unsetFlag("world", "letzteGabenQS");
        if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) await actor.unsetFlag("world", "letzteGabenMessageId");
    };

    const ladeActor = async uuid => {
        if (!uuid) return null;
        try {
            const doc = await fromUuid(uuid);
            return doc?.documentName === "Token" ? doc.actor : doc || null;
        } catch (error) {
            console.warn("Tanz der Klingen: Actor konnte nicht geladen werden.", { uuid, error });
            return null;
        }
    };

    const hatAphasmasSchleier = actor =>
        (actor?.effects || []).some(e =>
            !e.disabled && (
                e.getFlag("dsk", "isAphasmasSchleier") === true ||
                String(e.name || e.label || "").toLowerCase().includes("aphasmas schleier")
            )
        );

    const istErwacht = actor =>
        Boolean(actor && (
            DSK_FW.Effekt.CheckTarget(actor, "erwachte") ||
            DSK_FW.Wesen.match(actor, ["erwacht", "erwachter", "erwachte", "katze", "katzen"])
        ));

    const findeCasterEffekte = actor =>
        (actor?.effects || []).filter(e => (e.name || e.label || "") === vollerName);

    const findeZielEffekte = (actor, casterUuid) =>
        (actor?.effects || []).filter(e =>
            (e.name || e.label || "") === zielEffektName &&
            (!casterUuid || !e.getFlag("dsk", "linkedActorUuid") || e.getFlag("dsk", "linkedActorUuid") === casterUuid)
        );

    const beschreibungFuer = (casterName, qs) => {
        const willenskraftMalus = qs * 4;
        const attackeMalus = qs;
        return `<b>${casterName}</b> beginnt, den wirbelnden Tanz der Klingen aufzuführen.` +
            `<br><br>Die Verzauberten müssen eine <b>Willenskraft-Probe (−${willenskraftMalus})</b> bestehen, um angreifen zu können. ` +
            `Gelingt dies, sind ihre Attacken dennoch um <b>${attackeMalus} erschwert</b>.` +
            `<br><br>• <b>Willenskraft:</b> −${willenskraftMalus} (${qs} QS × 4)` +
            `<br>• <b>Angriff (NK / FK / Zauber):</b> −${attackeMalus} (${qs} QS)` +
            `<br><br><b>Voraussetzung:</b> Aphasmas Schleier | <b>Zielkategorie:</b> Erwachte`;
    };

    // +++ 4 - EFFEKTE ANWENDEN ++++++++++++++++++++++++++++++++++++
    const wendeCasterEffektAn = async ({ casterActor, qs }) => {
        const alteCasterEffekte = findeCasterEffekte(casterActor);
        if (alteCasterEffekte.length) {
            await casterActor.deleteEmbeddedDocuments("ActiveEffect", alteCasterEffekte.map(e => e.id));
        }

        const casterEffekt = await DSK_FW.Effekt.Anwenden({
            name: vollerName,
            ahne,
            beschreibung:
                `Führt einen schnellen Einzeltanz auf und verzaubert Feinde. Der Tänzer kann währenddessen keine anderen Aktionen ausführen.` +
                `<br><br><b>Wirkungsdauer:</b> ${dauerText}`,
            gabeZiel: "erwachte",
            qs,
            ziel: casterActor,
            changes: [],
            showIcon: 1,
            flags: {
                dsk: {
                    isTanzDerKlingenCaster: true,
                    casterUuid: casterActor.uuid,
                    qs,
                    wirkungsende: {
                        sfName: endeKey,
                        basisEffektName: vollerName,
                        beschreibungFuerEnde: endeText
                    }
                }
            }
        });

        return Boolean(
            casterEffekt &&
            (casterEffekt.name || casterEffekt.label || "") === vollerName &&
            casterEffekt.getFlag("dsk", "isTanzDerKlingenCaster") === true
        );
    };

    const wendeZielEffektAn = async ({ casterActor, targetActor, qs }) => {
        if (!casterActor || !targetActor || !istErwacht(targetActor)) return false;

        const willenskraftMalus = qs * 4;
        const attackeMalus = qs;

        const alteZielEffekte = findeZielEffekte(targetActor, casterActor.uuid);
        if (alteZielEffekte.length) {
            await targetActor.deleteEmbeddedDocuments("ActiveEffect", alteZielEffekte.map(e => e.id));
        }

        const direkteChanges = [
            { key: "system.skillModifiers.FW", mode: 0, value: `Willenskraft -${willenskraftMalus}`, priority: 20 },
            { key: "system.rangeStats.attack", mode: 2, value: -attackeMalus, priority: 20 },
            { key: "system.meleeStats.attack", mode: 2, value: -attackeMalus, priority: 20 },
            { key: "system.spellStats.damage", mode: 2, value: -attackeMalus, priority: 20 }
        ];

        const zielEffekt = await DSK_FW.Effekt.Anwenden({
            name: zielEffektName,
            ahne,
            beschreibung:
                `Ist vom Tanz der Klingen verzaubert.` +
                `<br><br><b>Willenskraft:</b> −${willenskraftMalus} (zum Angreifen nötig)` +
                `<br><b>Attacke / Fernkampf / Zauber:</b> −${attackeMalus}` +
                `<br><b>Wirkungsdauer:</b> ${dauerText}`,
            gabeZiel: "erwachte",
            qs,
            ziel: targetActor,
            changes: direkteChanges,
            showIcon: 1,
            flags: {
                dsk: {
                    isTanzDerKlingenZiel: true,
                    casterUuid: casterActor.uuid,
                    linkedActorUuid: casterActor.uuid,
                    qs,
                    willenskraftMalus,
                    attackeMalus,
                    wirkungsende: {
                        sfName: endeKey,
                        basisEffektName: vollerName,
                        beschreibungFuerEnde: endeText
                    }
                }
            }
        });

        if (!zielEffekt) return false;

        const changes = zielEffekt.changes || [];
        const hatWK = changes.some(c => c.key === "system.skillModifiers.FW" && String(c.value) === `Willenskraft -${willenskraftMalus}`);
        const hatFK = changes.some(c => c.key === "system.rangeStats.attack" && Number(c.mode) === 2 && Number(c.value) === -attackeMalus);
        const hatNK = changes.some(c => c.key === "system.meleeStats.attack" && Number(c.mode) === 2 && Number(c.value) === -attackeMalus);
        const hatZauber = changes.some(c => c.key === "system.spellStats.damage" && Number(c.mode) === 2 && Number(c.value) === -attackeMalus);

        return Boolean(
            zielEffekt.parent?.uuid === targetActor.uuid &&
            zielEffekt.getFlag("dsk", "isTanzDerKlingenZiel") === true &&
            zielEffekt.getFlag("dsk", "linkedActorUuid") === casterActor.uuid &&
            hatWK && hatFK && hatNK && hatZauber
        );
    };

    // +++ 5 - GM-ANFRAGE VERARBEITEN +++++++++++++++++++++++++++++
    const verarbeiteAnfrage = async (casterActor, daten) => {
        if (!game.user.isGM || !casterActor || !daten) return false;

        if (daten.casterUuid && daten.casterUuid !== casterActor.uuid) {
            ui.notifications.warn("Luna sagt 🌙: Die gespeicherte Anfrage passt nicht zum Wirkenden.");
            return false;
        }

        if (daten.sceneId && daten.sceneId !== canvas.scene?.id) {
            ui.notifications.warn(`Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`);
            return false;
        }

        const qs = Math.max(1, Math.floor(Number(daten.qs) || 1));
        const willenskraftMalus = qs * 4;
        const attackeMalus = qs;
        const casterName = daten.casterName || DSK_FW.ResolveTokenName(casterActor);
        const erfolge = [], misserfolge = foundry.utils.deepClone(daten.misserfolge || []);

        for (const ziel of daten.ziele || []) {
            const targetActor = await ladeActor(ziel.actorUuid);
            const targetName = ziel.name || DSK_FW.ResolveTokenName(targetActor) || "Unbekanntes Ziel";

            if (!targetActor || !istErwacht(targetActor)) {
                misserfolge.push({ name: targetName });
                continue;
            }

            try {
                const ok = await wendeZielEffektAn({ casterActor, targetActor, qs });
                if (ok) {
                    erfolge.push({
                        name: `${targetName} (WK −${willenskraftMalus}, AT −${attackeMalus})`,
                        rolle: "Verzaubertes Ziel"
                    });
                } else {
                    misserfolge.push({ name: targetName });
                }
            } catch (error) {
                console.error("Tanz der Klingen: Effektanlage auf Ziel fehlgeschlagen.", { ziel, error });
                misserfolge.push({ name: targetName });
            }
        }

        let erfolgreich = erfolge.length > 0;

        if (erfolgreich) {
            const casterOk = await wendeCasterEffektAn({ casterActor, qs });
            if (!casterOk) erfolgreich = false;
        }

        await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
            messageId: daten.messageId,
            gabenName: vollerName,
            ahne,
            beschreibung: daten.beschreibung || beschreibungFuer(casterName, qs),
            wirkender: casterName,
            ziele: erfolge,
            misserfolge,
            dauerText: `${dauerText} (${qs} QS)`,
            erfolgreich
        });

        if (erfolgreich) {
            ui.notifications.info(
                `Luna sagt 🌙: Tanz der Klingen verzaubert ${erfolge.length} Ziel(e).`
            );
        } else {
            ui.notifications.error(
                "Luna sagt 🌙: Tanz der Klingen konnte auf kein Ziel angewendet werden!"
            );
        }

        return true;
    };

    // +++ 6 - GM-MODUS ++++++++++++++++++++++++++++++++++++++++++++
    if (game.user.isGM) {
        const anfragen = DSK_FW.GMAnfrage.Finden(flagKey);

        if (anfragen.length) {
            for (const anfrageActor of anfragen) {
                const daten = DSK_FW.GMAnfrage.Lesen(anfrageActor, flagKey);
                if (!daten) continue;

                if (await verarbeiteAnfrage(anfrageActor, daten)) {
                    await DSK_FW.GMAnfrage.Loeschen(anfrageActor, flagKey);
                }
            }

            return;
        }
    }

    // +++ 7 - WIRKENDER +++++++++++++++++++++++++++++++++++++++++++
    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;

    if (!casterActor) {
        casterActor =
            canvas.tokens.placeables.map(token => token.actor).find(actor =>
                actor?.getFlag("world", "letzteGabenQS") !== undefined
            ) ||
            game.actors.find(actor =>
                actor.getFlag("world", "letzteGabenQS") !== undefined
            ) ||
            null;
    }

    if (!casterActor) {
        return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");
    }

    if (!game.user.isGM && !casterActor.isOwner) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!"
        );
    }

    const casterToken = DSK_FW.Token.Finde(casterActor);
    if (!casterToken) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Der Wirkende braucht einen Token auf der aktuellen Szene!"
        );
    }

    const casterName = DSK_FW.ResolveTokenName(casterActor);

    // +++ 8 - QS ++++++++++++++++++++++++++++++++++++++++++++++++++
    const qs = DSK_FW.QS.Ermitteln({
        actor: casterActor,
        gabenName,
        suchbegriffe: ["Tanz der Klingen Probe", "Tanz der Klingen"],
        testDataObj: typeof testData !== "undefined" ? testData : null,
        fallback: 0,
        protokollieren: true
    });

    if (qs <= 0) {
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName: vollerName,
            ahne,
            beschreibung: "Der hypnotische Tanz der Klingen konnte nicht aufgeführt werden.",
            wirkender: casterName,
            ziele: [],
            misserfolge: [{ name: casterName }],
            dauerText: "Keine Wirkung",
            gmBereich: false,
            angewendet: true,
            erfolgreich: false,
            anfragenderUserId: game.user.id
        });

        await raeumeQSAuf(casterActor);
        return;
    }

    // +++ 9 - PRÜFUNG: APHASMAS SCHLEIER AKTIV? +++++++++++++++++++
    if (!hatAphasmasSchleier(casterActor)) {
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName: vollerName,
            ahne,
            beschreibung: "Kein geweihter Schleier getragen! Der Tanz kann nur ausgeführt werden, während <b>Aphasmas Schleier</b> aktiv ist.",
            wirkender: casterName,
            ziele: [],
            misserfolge: [{ name: casterName }],
            dauerText: "Keine Wirkung",
            gmBereich: false,
            angewendet: true,
            erfolgreich: false,
            anfragenderUserId: game.user.id
        });

        await raeumeQSAuf(casterActor);
        return;
    }

    // +++ 10 - TARGETS PRÜFEN (ALLE ERWACHTEN = ERFOLG, REST = MISSERFOLG) +++
    const targets = Array.from(game.user.targets || []);

    if (!targets.length) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.warn(
            "Luna sagt 🌙: Bitte wähle zuerst die Feinde per Target aus!"
        );
    }

    const willenskraftMalus = qs * 4;
    const attackeMalus = qs;
    const gueltigeZiele = [];
    const misserfolge = [];

    for (const tToken of targets) {
        const tActor = tToken?.actor;
        const tName = tToken?.name || tActor?.name || "Unbekanntes Ziel";

        if (!tActor || tActor.uuid === casterActor.uuid || !istErwacht(tActor)) {
            misserfolge.push({ name: tName });
            continue;
        }

        gueltigeZiele.push({
            actorUuid: tActor.uuid,
            tokenId: tToken.id,
            tokenUuid: tToken.document?.uuid || tToken.uuid || null,
            name: tName
        });
    }

    const beschreibung = beschreibungFuer(casterName, qs);

    if (!gueltigeZiele.length) {
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName: vollerName,
            ahne,
            beschreibung: "Keines der gewählten Ziele ist ein gültiger Erwachter.",
            wirkender: casterName,
            ziele: [],
            misserfolge,
            dauerText: "Keine Wirkung",
            gmBereich: false,
            angewendet: true,
            erfolgreich: false,
            anfragenderUserId: game.user.id
        });

        await raeumeQSAuf(casterActor);
        return;
    }

    // +++ 11 - GEMEINSAME KARTE + GM-BUTTON +++++++++++++++++++++++
    const gmLink = DSK_FW.GabenUI.GMMakroButton(
        macroUuid,
        "Effekt anwenden",
        "Das Makro muss durch die Spielleitung ausgeführt werden."
    );

    const nachricht = await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName,
        ahne,
        beschreibung,
        wirkender: casterName,
        ziele: gueltigeZiele.map(z => ({
            name: `${z.name} (WK −${willenskraftMalus}, AT −${attackeMalus})`,
            rolle: "Verzaubertes Ziel"
        })),
        misserfolge,
        dauerText: `${dauerText} (${qs} QS)`,
        gmLink,
        gmBereich: !game.user.isGM,
        anfragenderUserId: game.user.id
    });

    if (!nachricht) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.error(
            "Luna sagt 🌙: Die Wirkungskarte konnte nicht erstellt werden!"
        );
    }

    const anfrageDaten = {
        casterUuid: casterActor.uuid,
        casterName,
        casterTokenId: casterToken.id,
        casterTokenUuid: casterToken.document?.uuid || casterToken.uuid || null,
        ziele: gueltigeZiele,
        misserfolge,
        qs,
        beschreibung,
        sceneId: canvas.scene?.id || null,
        requestedByUserId: game.user.id,
        messageId: nachricht.id,
        macroUuid,
        erstellt: Date.now()
    };

    // +++ 12 - DIREKT ODER GM-ANFRAGE +++++++++++++++++++++++++++++
    if (game.user.isGM) {
        await verarbeiteAnfrage(casterActor, anfrageDaten);
        await raeumeQSAuf(casterActor);
        return;
    }

    await DSK_FW.GMAnfrage.Speichern(casterActor, flagKey, anfrageDaten);
    await raeumeQSAuf(casterActor);

    ui.notifications.info(
        "Luna sagt 🌙: Tanz der Klingen wurde bei der Spielleitung zur Anwendung beantragt."
    );
}).call(this);
